// The card set. This is the only source: the board, the gallery and the bot all
// read from here. In Cards of Cronos the card data lived in two files, one for the
// engine and one for the frontend, and the frontend failed to ship eight times.
// One file, one truth.
//
// The rules text on a card is not stored here. It is generated from the effect by
// engine/rules-text.ts, so what a card promises and what it does cannot drift
// apart. What is written here is `flavour`: prose that promises nothing.
//
// Numbers per tier, as a guide when adding cards:
//   common     launch 12-18K   pump  7-10K   holders 2
//   rare       launch 22-30K   pump 14-17K   holders 3
//   epic       launch 36-45K   pump 22-27K   holders 3-4
//   legendary  launch 60-75K   pump 38-44K   holders 4
//   mythic     launch 110-125K pump 55-62K   holders 5

import type {
  Card,
  EventCard,
  InfluencerCard,
  ProjectCard,
  TacticCard,
  ToolCard,
} from "@/engine/types";

