// ---------------------------------------------------------------------------
// Projects, fourth wave — 5
//
// Three names that were asked for and missing, plus two cards of a shape the set
// did not have.
//
// Every project here ran between 1.2 and 2.6 times as much launch as pump: they
// all arrive worth something and then keep paying. Nothing spiked and died,
// which is half of what actually happens down there. HAWK and JENNER are that
// half — around twenty times the launch of their pump, one holder, and no second
// act.
//
// What that actually makes them, measured rather than assumed: a card worth
// roughly the same whenever it is played, unlike everything else in the set,
// which is worth more the earlier it lands. So the turn you play it is decided
// by risk instead of by tempo — one holder and the whole launch counted as
// unrealised means an early HAWK is a rug waiting to happen, and a last-turn
// HAWK cannot be touched. The bot does not model that and plays them on turn
// 5.5, about when it plays any other epic. A person should not.
// ---------------------------------------------------------------------------

