//
// These cards carry the names of real people. That is normal in this corner of
// the market, but who ends up on one is the maker's call — which is why they sit
// together here rather than scattered around. Want someone out? You only touch
// this block; the rest of the set never notices.
//
// The bar is the same as for projects: a name the trenches know, and a Solana
// story. Pauly was here on an nft aura and failed both. Pauly0x is Jeremy Cahen,
// whose story is an Ethereum one — NotLarvaLabs, and the Yuga Labs trademark
// case he lost, which by February 2024 stood at roughly $9M including fees, with
