// ---------------------------------------------------------------------------
// Projects, fifth wave — 60
//
// Not "more cards" so much as "the other seven sectors". Before this the set had
// 41 meme projects and between four and eleven of everything else, which meant
// exactly one theme was really buildable: a deck needs twelve projects and you
// build towards a theme, so a sector with five cards in it is a sector nobody
// can lean on. Every sector here comes out at fifteen or more.
//
// Mostly commons and rares, deliberately. The thin sectors were thin at the
// bottom — infra had no common and no rare at all, so an infra deck was
// unbuildable until you had pulled an epic. Rarity should say how big a card is,
// not which sectors exist for you.
//
// A lot of these are old Solana rather than new: FIDA, SRM, MNGO, SBR, TULIP,
// COPE. They went hard and most of them are worth close to nothing now, which is
// the trenches as much as anything currently running.
// ---------------------------------------------------------------------------

